// Vectors in testdata/ were generated by the JDK 21 runtime that the pinned
// Closure Compiler oracle runs on (see tools/oracle/README.md).

func TestDoubleToStringMatchesJava(t *testing.T) {
	f, err := os.Open("testdata/double_tostring.tsv")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	n, bad := 0, 0
	for sc.Scan() {
		parts := strings.Split(sc.Text(), "\t")
		bits, _ := strconv.ParseUint(parts[0], 16, 64)
		d := math.Float64frombits(bits)
		n++
		if got := DoubleToString(d); got != parts[1] {
			bad++
			if bad < 20 {
				t.Errorf("DoubleToString(%x) = %q, Java %q", bits, got, parts[1])
			}
		}
		if got := strconv.FormatInt(int64(D2I(d)), 10); got != parts[2] {
			t.Errorf("D2I(%v) = %s, Java %s", d, got, parts[2])
		}
		if got := strconv.FormatInt(D2L(d), 10); got != parts[3] {
			t.Errorf("D2L(%v) = %s, Java %s", d, got, parts[3])
		}
	}
	if n < 20000 {
		t.Fatalf("only %d vectors", n)
	}
	if bad > 0 {
		t.Fatalf("%d/%d mismatches", bad, n)
	}
}

func decodeHexUTF16(s string) []uint16 {
	s = strings.TrimPrefix(s, "x")
	var out []uint16
	for i := 0; i+4 <= len(s); i += 4 {
		v, _ := strconv.ParseUint(s[i:i+4], 16, 16)
		out = append(out, uint16(v))
	}
	return out
}

func sign(x int) int {
	switch {
	case x < 0:
		return -1
	case x > 0:
		return 1
	}
	return 0
}

func TestStringSemanticsMatchJava(t *testing.T) {
	f, err := os.Open("testdata/strings.tsv")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		p := strings.Split(sc.Text(), "\t")
		ua, ub := decodeHexUTF16(p[0]), decodeHexUTF16(p[1])
		a, b := StringFromUTF16(ua), StringFromUTF16(ub)
		// Round trip through WTF-8 must be lossless, lone surrogates included.
		if back := StringToUTF16(a); !equalU16(back, ua) {
			t.Fatalf("round trip %v -> %q -> %v", ua, a, back)
		}
		wantHash, _ := strconv.ParseInt(p[2], 10, 32)
		if h := StringHashCode(a); int64(h) != wantHash {
			t.Errorf("hashCode(%v) = %d, Java %d", ua, h, wantHash)
		}
		wantCmp, _ := strconv.Atoi(p[3])
		if c := sign(StringCompareTo(a, b)); c != wantCmp {
			t.Errorf("compareTo(%v, %v) = %d, Java %d", ua, ub, c, wantCmp)
		}
		wantLen, _ := strconv.Atoi(p[4])
		if l := StringLength(a); l != wantLen {
			t.Errorf("length(%v) = %d, Java %d", ua, l, wantLen)
		}
		for i := range ua {
			if c := StringCharAt(a, i); c != ua[i] {
				t.Errorf("charAt(%v, %d) = %x, want %x", ua, i, c, ua[i])
			}
		}
		for beg := 0; beg <= len(ua); beg++ {
			if got := StringToUTF16(StringSubstringFrom(a, beg)); !equalU16(got, ua[beg:]) {
				t.Errorf("substringFrom(%v, %d) = %v, want %v", ua, beg, got, ua[beg:])
			}
			for end := beg; end <= len(ua); end++ {
				if got := StringToUTF16(StringSubstring(a, beg, end)); !equalU16(got, ua[beg:end]) {
					t.Errorf("substring(%v, %d, %d) = %v, want %v", ua, beg, end, got, ua[beg:end])
				}
			}
		}
	}
}

func equalU16(a, b []uint16) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func TestTryCatchesSubclasses(t *testing.T) {
	var got string
	Try(func() { panic(NewIllegalStateExceptionMsg("boom")) }, func(e IRuntimeException) { got = e.Error() })
	if got != "java.lang.IllegalStateException: boom" {
		t.Fatalf("got %q", got)
	}
	// A non-matching catch must let the exception propagate.
	defer func() {
		if r := recover(); r == nil {
			t.Fatal("expected propagation")
		}
	}()
	Try(func() { panic(NewIllegalArgumentException()) }, func(e IIllegalStateException) { t.Fatal("wrong catch") })
}

func TestTryWrapsRuntimeErrors(t *testing.T) {
	caught := false
	Try(func() {
		var p *int
		_ = *p // nil dereference, Java NullPointerException
	}, func(e IRuntimeException) { caught = true })
	if !caught {
		t.Fatal("runtime error not caught as RuntimeException")
	}
}

func TestOrderedMapOrder(t *testing.T) {
	m := NewOrderedMap[string, int]()
	for i, k := range []string{"z", "a", "m", "b"} {
		m.Put(k, i)
	}
	m.Put("a", 10) // re-put keeps position
	m.Remove("m")
	m.Put("m", 20) // re-insert goes to the end
	var keys []string
	for k, v := range m.All() {
		keys = append(keys, k+"="+strconv.Itoa(v))
		if k == "z" {
			m.Remove("b") // removal during iteration is skipped
		}
	}
	if got := strings.Join(keys, ","); got != "z=0,a=10,m=20" {
		t.Fatalf("order = %s", got)
	}
	if m.String() != "{z=0, a=10, m=20}" {
		t.Fatalf("String() = %s", m.String())
	}
}

func TestLenientFormat(t *testing.T) {
	if got := LenientFormat("a %s b %s", 1, "x", 2.5, nil); got != "a 1 b x [2.5, null]" {
		t.Fatalf("got %q", got)
	}
}

func TestFixedArityPreconditionsDoNotAllocate(t *testing.T) {
	x, y := int64(123456), 654321
	if n := testing.AllocsPerRun(100, func() {
		CheckArgumentMsg2(true, "a %s b %s", x, y)
		CheckStateMsg3(true, "%s %s %s", x, y, "s")
	}); n != 0 {
		t.Fatalf("success path allocates %v times", n)
	}
	var got string
	Try(func() { CheckArgumentMsg2(false, "a %s b %s", x, y) }, func(e IIllegalArgumentException) { got = e.GetMessage() })
	if got != "a 123456 b 654321" {
		t.Fatalf("message %q", got)
	}
}

func TestWTF8IndexingZeroAllocAndBounds(t *testing.T) {
	s := "hello_é_😀_world"
	if n := testing.AllocsPerRun(100, func() {
		_ = StringCharAt(s, 0)
		_ = StringCharAt(s, 6)
		_ = StringCharAt(s, 8)
		_ = StringCharAt(s, 9)
		_ = StringSubstring(s, 0, 5)
		_ = StringSubstring(s, 6, 10)
		_ = StringSubstringFrom(s, 8)
	}); n != 0 {
		t.Fatalf("expected 0 allocs on non-splitting WTF-8 indexing, got %v", n)
	}
	// Splitting astral surrogate pairs [0xD83D, 0xDE00] and [0xD83D, 0xDE01]
	twoEmoji := "😀😁"
	if got := StringToUTF16(StringSubstring(twoEmoji, 1, 3)); !equalU16(got, []uint16{0xDE00, 0xD83D}) {
		t.Fatalf("split both surrogates = %x", got)
	}
	if got := StringToUTF16(StringSubstringFrom(twoEmoji, 1)); !equalU16(got, []uint16{0xDE00, 0xD83D, 0xDE01}) {
		t.Fatalf("split begin surrogate = %x", got)
	}
	assertOOB := func(fn func(), want string) {
		t.Helper()
		var gotMsg string
		Try(fn, func(e IIndexOutOfBoundsException) { gotMsg = e.GetMessage() })
		if gotMsg != want {
			t.Fatalf("got %q, want %q", gotMsg, want)
		}
	}
	assertOOB(func() { StringCharAt(twoEmoji, -1) }, "Index -1 out of bounds for length 4")
	assertOOB(func() { StringCharAt(twoEmoji, 4) }, "Index 4 out of bounds for length 4")
	assertOOB(func() { StringSubstring(twoEmoji, -1, 2) }, "Range [-1, 2) out of bounds for length 4")
	assertOOB(func() { StringSubstring(twoEmoji, 3, 2) }, "Range [3, 2) out of bounds for length 4")
	assertOOB(func() { StringSubstring(twoEmoji, 0, 5) }, "Range [0, 5) out of bounds for length 4")
	assertOOB(func() { StringSubstringFrom(twoEmoji, -1) }, "Range [-1, 4) out of bounds for length 4")
	assertOOB(func() { StringSubstringFrom(twoEmoji, 5) }, "Range [5, 4) out of bounds for length 4")
}

func TestStringWTF8LoneSurrogates(t *testing.T) {
	hi := StringFromChar(0xD83D)
	lo := StringFromChar(0xDE00)
	pair := "😀" // U+1F600 -> [0xD83D, 0xDE00] in UTF-16, 4-byte F0 9F 98 80 in UTF-8

	if got := StringIndexOf("a"+pair+"b", hi); got != 1 {
		t.Fatalf("StringIndexOf(hi) = %d, want 1", got)
	}
	if got := StringIndexOf("a"+pair+"b", lo); got != 2 {
		t.Fatalf("StringIndexOf(lo) = %d, want 2", got)
	}
	if got := StringIndexOfFrom(pair+pair, lo, 2); got != 3 {
		t.Fatalf("StringIndexOfFrom(lo, 2) = %d, want 3", got)
	}
	if got := StringLastIndexOf(pair+"x"+pair, hi); got != 3 {
		t.Fatalf("StringLastIndexOf(hi) = %d, want 3", got)
	}
	if !StringStartsWith(pair+"abc", hi) || StringStartsWith(pair+"abc", lo) {
		t.Fatal("StringStartsWith lone-surrogate mismatch")
	}
	if !StringEndsWith("abc"+pair, lo) || StringEndsWith("abc"+pair, hi) {
		t.Fatal("StringEndsWith lone-surrogate mismatch")
	}

	// Removing "x" between a lone high surrogate and lone low surrogate must
	// merge the pair into canonical 4-byte UTF-8.
	merged := StringReplace(hi+"x"+lo, "x", "")
	if merged != pair || len(merged) != 4 || hasSurrogateByte(merged) {
		t.Fatalf("StringReplace merge = %q (len=%d), want canonical %q", merged, len(merged), pair)
	}
	// Replacing half of an astral character with another surrogate or ASCII.
	splitReplaced := StringReplace(pair, hi, "H")
	if want := "H" + lo; splitReplaced != want {
		t.Fatalf("StringReplace half = %x, want %x", []byte(splitReplaced), []byte(want))
	}
	// Empty target inserts between surrogate halves in Java UTF-16 semantics.
	emptyTarget := StringReplace(pair, "", "_")
	if want := "_" + hi + "_" + lo + "_"; emptyTarget != want {
		t.Fatalf("StringReplace empty target = %x, want %x", []byte(emptyTarget), []byte(want))
	}

	// Fast path without 0xED must remain zero-alloc.
	clean := "alpha_😀_beta"
	if n := testing.AllocsPerRun(100, func() {
		_ = StringIndexOf(clean, "beta")
		_ = StringIndexOfFrom(clean, "beta", 2)
		_ = StringLastIndexOf(clean, "alpha")
		_ = StringStartsWith(clean, "alpha")
		_ = StringEndsWith(clean, "beta")
		_ = StringReplace(clean, "missing", "x")
	}); n != 0 {
		t.Fatalf("expected 0 allocs on canonical fast path, got %v", n)
	}
}

func TestOrderedMapNonMutatingReadsAndFrom(t *testing.T) {
	m := NewOrderedMap[string, int]()
	for i := 0; i < 10; i++ {
		m.Put("k"+strconv.Itoa(i), i)
	}
	m.Delete("k1")
	m.Delete("k5") // leaves holes == 2 (2*2 < 10, so uncompacted)
	if m.holes != 2 {
		t.Fatalf("expected holes == 2, got %d", m.holes)
	}

	wantKeys := []string{"k0", "k2", "k3", "k4", "k6", "k7", "k8", "k9"}
	wantVals := []int{0, 2, 3, 4, 6, 7, 8, 9}

	var wg sync.WaitGroup
	for g := 0; g < 8; g++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := 0; i < 50; i++ {
				if fk, fv, ok := m.First(); !ok || fk != "k0" || fv != 0 {
					t.Errorf("First() = (%q, %d, %v)", fk, fv, ok)
				}
				if got, ok := m.Index("k6"); !ok || got != 4 {
					t.Errorf("Index(k6) = (%d, %v), want (4, true)", got, ok)
				}
				if got, ok := m.ValueAt(4); !ok || got != 6 {
					t.Errorf("ValueAt(4) = (%d, %v), want (6, true)", got, ok)
				}
				if !slices.Equal(m.KeySlice(), wantKeys) {
					t.Errorf("KeySlice mismatch")
				}
				if !slices.Equal(m.ValueSlice(), wantVals) {
					t.Errorf("ValueSlice mismatch")
				}
				if len(m.Entries()) != 8 {
					t.Errorf("Entries len = %d", len(m.Entries()))
				}
				if m.String() != "{k0=0, k2=2, k3=3, k4=4, k6=6, k7=7, k8=8, k9=9}" {
					t.Errorf("String() = %q", m.String())
				}
				_ = m.Clone()
				_ = m.ToMap()
				_ = m.HashCode()
				for range m.All() {
				}
				for range m.Keys() {
				}
				for range m.Values() {
				}
			}
		}()
	}
	wg.Wait()

	if m.holes != 2 {
		t.Fatalf("read methods mutated holes: got %d, want 2", m.holes)
	}

	cp := NewOrderedMapFrom(m)
	if !cp.EqualFunc(m, func(a, b int) bool { return a == b }) || cp.HashCode() != m.HashCode() {
		t.Fatal("NewOrderedMapFrom mismatch")
	}

	var nilSrc *OrderedMap[string, int]
	if emptyFromNil := NewOrderedMapFrom(nilSrc); emptyFromNil.Len() != 0 {
		t.Fatalf("NewOrderedMapFrom(nil) len = %d, want 0", emptyFromNil.Len())
	}
}
